import { env } from "cloudflare:workers";

export type Todo = {
  id: string;
  title: string;
  done: boolean;
  createdAt: number;
};

const PREFIX = "todo:";

export async function getAllTodos(): Promise<Todo[]> {
  const list = await env.TODOS.list({ prefix: PREFIX });
  const todos: Todo[] = [];
  for (const key of list.keys) {
    const value = await env.TODOS.get(key.name);
    if (value) {
      todos.push(JSON.parse(value));
    }
  }
  // sort by createdAt ascending
  todos.sort((a, b) => a.createdAt - b.createdAt);
  return todos;
}

export async function createTodo(title: string): Promise<Todo> {
  const id = crypto.randomUUID();
  const todo: Todo = {
    id,
    title,
    done: false,
    createdAt: Date.now(),
  };
  await env.TODOS.put(PREFIX + id, JSON.stringify(todo));
  return todo;
}

export async function toggleTodoInKV(id: string, done: boolean): Promise<void> {
  const value = await env.TODOS.get(PREFIX + id);
  if (!value) return;
  const todo: Todo = JSON.parse(value);
  todo.done = done;
  await env.TODOS.put(PREFIX + id, JSON.stringify(todo));
}

export async function deleteTodoFromKV(id: string): Promise<void> {
  await env.TODOS.delete(PREFIX + id);
}
```

