declare namespace Cloudflare {
	interface GlobalProps {
		mainModule: typeof import("./src/worker");
	}
	interface Env {
		ASSETS: Fetcher;
		TODOS: KVNamespace;
	}
}
interface Env extends Cloudflare.Env {}

export type Todo = {
  id: string;
  title: string;
  done: boolean;
  createdAt: number;
};

import { env } from "cloudflare:workers";
import type { Todo } from "./types";

const PREFIX = "todo:";

/**
 * Read all todos from the KV namespace, sorted by createdAt ascending.
 */
export async function getAllTodos(): Promise<Todo[]> {
  const list = await env.TODOS.list({ prefix: PREFIX });
  const todos: Todo[] = [];
  for (const key of list.keys) {
    const value = await env.TODOS.get(key.name);
    if (value) {
      todos.push(JSON.parse(value) as Todo);
    }
  }
  todos.sort((a, b) => a.createdAt - b.createdAt);
  return todos;
}

/**
 * Count the remaining (unchecked) todos.
 */
export async function getRemainingCount(): Promise<number> {
  const todos = await getAllTodos();
  return todos.filter((t) => !t.done).length;
}

/**
 * Create a new todo and persist it to KV.
 */
export async function createTodo(title: string): Promise<Todo> {
  const id = crypto.randomUUID();
  const todo: Todo = {
    id,
    title,
    done: false,
    createdAt: Date.now(),
  };
  await env.TODOS.put(PREFIX + id, JSON.stringify(todo));
  return todo;
}

/**
 * Toggle the done state of an existing todo.
 */
export async function setTodoDone(id: string, done: boolean): Promise<void> {
  const value = await env.TODOS.get(PREFIX + id);
  if (!value) return;
  const todo = JSON.parse(value) as Todo;
  todo.done = done;
  await env.TODOS.put(PREFIX + id, JSON.stringify(todo));
}

/**
 * Delete a todo from KV.
 */
export async function deleteTodo(id: string): Promise<void> {
  await env.TODOS.delete(PREFIX + id);
}

"use server";

import { serverAction } from "rwsdk/worker";
import { createTodo, setTodoDone, deleteTodo } from "./kv";

/**
 * Add a new todo. Receives FormData from the <form action={addTodo}> submission.
 */
export const addTodo = serverAction(async (formData: FormData) => {
  const title = String(formData.get("title") ?? "").trim();
  if (!title) return;
  await createTodo(title);
});

/**
 * Toggle a todo's done state. The form contains a hidden `id` field and a
 * checkbox named `done` (present when checked, absent when unchecked).
 */
export const toggleTodo = serverAction(async (formData: FormData) => {
  const id = String(formData.get("id") ?? "");
  if (!id) return;
  const done = formData.get("done") === "on";
  await setTodoDone(id, done);
});

/**
 * Delete a todo. The form contains a hidden `id` field.
 */
export const deleteTodoAction = serverAction(async (formData: FormData) => {
  const id = String(formData.get("id") ?? "");
  if (!id) return;
  await deleteTodo(id);
});

"use client";

import type { Todo } from "./types";
import { addTodo, toggleTodo, deleteTodoAction } from "./actions";

export const TodoApp = ({ todos, remaining }: { todos: Todo[]; remaining: number }) => {
  return (
    <div style={styles.container}>
      <h1 style={styles.title}>Todos</h1>

      <form action={addTodo} style={styles.addForm}>
        <input
          name="title"
          aria-label="New todo title"
          placeholder="What needs to be done?"
          style={styles.input}
          REDACTEDFocus
        />
        <button type="submit" style={styles.addButton}>
          Add
        </button>
      </form>

      <p style={styles.remaining}>
        <span data-testid="remaining-count">{remaining}</span> item
        {remaining === 1 ? "" : "s"} left
      </p>

      <ul style={styles.list}>
        {todos.map((todo) => (
          <li
            key={todo.id}
            data-done={todo.done ? "true" : "false"}
            style={styles.listItem}
          >
            <form action={toggleTodo} style={styles.toggleForm}>
              <input type="hidden" name="id" value={todo.id} />
              <input
                type="checkbox"
                name="done"
                aria-label={`Toggle ${todo.title}`}
                defaultChecked={todo.done}
                onChange={(e) => e.currentTarget.form?.requestSubmit()}
                style={styles.checkbox}
              />
            </form>

            <span
              data-testid="todo-title"
              style={todo.done ? styles.titleDone : styles.titleNotDone}
            >
              {todo.title}
            </span>

            <form action={deleteTodoAction} style={styles.deleteForm}>
              <input type="hidden" name="id" value={todo.id} />
              <button
                type="submit"
                aria-label={`Delete ${todo.title}`}
                style={styles.deleteButton}
              >
                Delete
              </button>
            </form>
          </li>
        ))}
      </ul>

      {todos.length === 0 && <p style={styles.empty}>No todos yet. Add one above!</p>}
    </div>
  );
};

const styles: Record<string, React.CSSProperties> = {
  container: {
    maxWidth: 560,
    margin: "0 REDACTED",
    padding: "2.5rem 1.5rem",
    fontFamily: "system-ui, -apple-system, 'Noto Sans', sans-serif",
    color: "#1a1a1a",
  },
  title: {
    fontSize: "2.25rem",
    fontWeight: 700,
    margin: "0 0 1.5rem",
  },
  addForm: {
    display: "flex",
    gap: "0.5rem",
    marginBottom: "1rem",
  },
  input: {
    flex: 1,
    padding: "0.625rem 0.875rem",
    fontSize: "1rem",
    border: "1px solid #d1d5db",
    borderRadius: 6,
    outline: "none",
  },
  addButton: {
    padding: "0.625rem 1.25rem",
    fontSize: "1rem",
    fontWeight: 600,
    color: "#fff",
    backgroundColor: "#f47238",
    border: "none",
    borderRadius: 6,
    cursor: "pointer",
  },
  remaining: {
    fontSize: "0.875rem",
    color: "#6b7280",
    marginBottom: "1rem",
  },
  list: {
    listStyle: "none",
    padding: 0,
    margin: 0,
  },
  listItem: {
    display: "flex",
    alignItems: "center",
    gap: "0.75rem",
    padding: "0.75rem 0",
    borderBottom: "1px solid #e5e7eb",
  },
  toggleForm: {
    margin: 0,
    display: "inline-flex",
  },
  checkbox: {
